bool vectorized_AllPointsEq(const int pts[], int count) {
    if (count <= 0) return true;

    int first = pts[0];
    int result = 1;

    typedef int v8si __attribute__((vector_size(32)));

    int i = 1;

    if ((count - 1) >= 8) {
        v8si vfirst = {first, first, first, first, first, first, first, first};
        v8si vresult = {1, 1, 1, 1, 1, 1, 1, 1};

        for (; i + 7 < count; i += 8) {
            v8si vdata;
            memcpy(&vdata, &pts[i], sizeof(v8si));
            v8si vcmp = (vdata == vfirst);
            vresult &= vcmp;
        }

        int tmp[8];
        memcpy(tmp, &vresult, sizeof(tmp));
        for (int j = 0; j < 8; j++) {
            result &= (tmp[j] != 0);
        }
    }

    for (; i < count; i++) {
        result &= (first == pts[i]);
    }

    return (bool)result;
}

bool AllPointsEq(const int pts[], int count) {
    for (int i = 1; i < count; ++i) {
        if (pts[0] != pts[i]) {
            return false;
        }
    }
    return true;
}
